private void xrLabel50_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
 e.Result = totalipatvsh - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) - Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL")); 
            e.Handled = true;

}

private void xrLabel50_SummaryReset(object sender, System.EventArgs e) {
 totalipatvsh = 0;
}

private void xrLabel50_SummaryRowChanged(object sender, System.EventArgs e) {
totalipatvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
}

private void xrLabel51_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
   e.Result = (totalipatvshkursi - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) - Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL"))) * Convert.ToDouble(GetCurrentColumnValue("KURSI"));
            e.Handled = true;
}

private void xrLabel51_SummaryReset(object sender, System.EventArgs e) {
  totalipatvshkursi = 0;
}

private void xrLabel51_SummaryRowChanged(object sender, System.EventArgs e) {
 totalipatvshkursi += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
}

